/**
 * The tsconfig templates of pob:common:typescript, rendered to the exact
 * string ejs produced: the result is formatted with oxfmt, which keeps the
 * blank lines (whitespace-only lines included).
 */
import { escapeHtml } from "./escapeHtml.ts";

const generatedHeader =
  "// Generated by pob: do not edit, it is overwritten on each pob run.\n";

export interface TsconfigTemplateOptions {
  emitDefinitions: boolean;
  build: boolean;
  cacheEnabled: boolean;
  /** [package name, location], undefined outside a typescript monorepo */
  monorepoPackageSrcPaths: [string, string][] | undefined;
  monorepoPackageReferences: string[] | undefined;
  rootDir: string;
  srcDirectory: string;
  enableHashSlash: boolean;
  jsx: boolean;
  jsxPreserve: boolean;
  nextConfig: boolean;
  composite: boolean;
  /** the typescript setting of the monorepo: only its truthiness matters */
  incremental: unknown;
  dom: boolean;
  resolveJsonModule: boolean;
  forceExcludeNodeModules: boolean;
  forceAllowJs: boolean;
  plugins: string[];
  additionalIncludes: string[];
  presets: string[];
}

const renderOutput = ({
  emitDefinitions,
  build,
  composite,
  cacheEnabled,
  incremental,
}: TsconfigTemplateOptions): string => {
  const cacheFile =
    '    "tsBuildInfoFile": "node_modules/.cache/tsc/tsbuildinfo",\n';
  if (emitDefinitions || build) {
    return [
      `    "outDir": "${build ? "dist" : "dist/definitions"}",\n`,
      "    ",
      build ? '      "declarationDir": "dist/definitions",\n    ' : "",
      "    ",
      composite ? `${cacheFile}    ` : "",
    ].join("");
  }
  if (composite || incremental) {
    return `${
      composite && cacheEnabled
        ? '    "outDir": "node_modules/.cache/tsc",\n'
        : '    "noEmit": true,\n'
    }${cacheFile}`;
  }
  return `    "noEmit": true,\n${cacheFile}`;
};

const renderPaths = (
  srcDirectory: string,
  enableHashSlash: boolean,
  srcPaths: [string, string][] | undefined,
): string => {
  const hasSrcPaths = !!srcPaths && srcPaths.length > 0;
  if (!hasSrcPaths && !enableHashSlash) return "";
  const hashSlash = enableHashSlash
    ? `        "#/*": ["./${escapeHtml(srcDirectory)}/*"]${hasSrcPaths ? "," : ""}\n      `
    : "";
  const packages =
    hasSrcPaths && srcPaths
      ? `      ${srcPaths
          .map(
            ([packageName, packageLocation], index) =>
              `      "${escapeHtml(packageName)}": ["${escapeHtml(packageLocation)}"],\n      "${escapeHtml(packageName)}/*": ["${escapeHtml(packageLocation)}/*"]${index === srcPaths.length - 1 ? "" : ","}      `,
          )
          .join("")}\n      `
      : "";
  return `    "paths": {\n      ${hashSlash}${packages}\n    }`;
};

const renderReferences = (references: string[] | undefined): string => {
  if (!references || references.length === 0) return "";
  return `,\n  "references": [\n    ${references
    .map(
      (reference, index) =>
        `        { "path": "${escapeHtml(reference)}/tsconfig.json" }${index === references.length - 1 ? "" : ","}\n    `,
    )
    .join("")}  ],\n  `;
};

/** tsconfig.json.ejs */
export const renderTsconfig = (options: TsconfigTemplateOptions): string => {
  const {
    presets,
    srcDirectory,
    rootDir,
    jsx,
    additionalIncludes,
    forceExcludeNodeModules,
  } = options;
  const withoutPresets = presets.length === 0;
  return [
    generatedHeader,
    '{\n  "extends": [\n    "@pob/root/tsconfigs/strict.json"',
    presets.length > 0
      ? `,\n    ${presets.map((preset) => `"${preset}"`).join(",\n    ")}`
      : "",
    '\n  ],\n  "include": [\n',
    `    "${escapeHtml(srcDirectory)}/**/*.ts"`,
    jsx ? `,\n    "${escapeHtml(srcDirectory)}/**/*.tsx"` : "",
    srcDirectory === rootDir ? "" : `,\n    "${escapeHtml(rootDir)}/*.ts"`,
    additionalIncludes.length > 0
      ? `,\n    ${additionalIncludes.map((include) => `"${include}"`).join(",\n    ")}`
      : "",
    "\n  ],\n",
    srcDirectory === "." || forceExcludeNodeModules
      ? '  "exclude": [\n    "node_modules"\n  ],\n'
      : "",
    '  "compilerOptions": {\n',
    `    "rootDir": "${escapeHtml(rootDir)}",\n`,
    renderOutput(options),
    (options.composite && options.cacheEnabled) || options.emitDefinitions
      ? `    "noEmitOnError": true,\n    "declaration": true,\n    "declarationMap": true,\n    "emitDeclarationOnly": ${options.build ? "false" : "true"},\n`
      : "",
    (() => {
      if (options.composite) {
        return '    "incremental": true,\n    "composite": true,\n';
      }
      if (options.incremental) return '    "incremental": true,\n';
      return "";
    })(),
    "\n",
    withoutPresets
      ? `    "target": "esnext",                       /* Specify ECMAScript target version: 'ES3' (default), 'ES5', 'ES2015', 'ES2016', 'ES2017','ES2018' or 'ESNEXT'. */
    "module": "esnext",                       /* Specify module code generation: 'none', 'commonjs', 'amd', 'system', 'umd', 'es2015', or 'ESNext'. */
    "lib": [${options.dom ? '"dom", ' : ""}"esnext"],
    "isolatedModules": true,                  /* Transpile each file as a separate module (similar to 'ts.transpileModule'). */
`
      : "",
    jsx
      ? `    "jsx": "${options.jsxPreserve ? "preserve" : "react-jsx"}",                     /* 'react-jsx' is used with react/jsx-runtime (react >=17 || >= 16.14.0 | >= 15.7.0) */\n`
      : "",
    options.forceAllowJs ? '    "allowJs": true,\n' : "",
    options.nextConfig
      ? `    "strictNullChecks": true,
    "module": "esnext",
    "moduleResolution": "bundler",
    "lib": ["dom", "esnext"],
    "esModuleInterop": true,
    "isolatedModules": true,
`
      : "",
    "  ",
    options.resolveJsonModule ? '    "resolveJsonModule": true,\n  ' : "",
    options.plugins.length > 0
      ? `    "plugins": [${options.plugins.map((pluginName) => `{"name": "${pluginName}"}`).join(", ")}],\n`
      : "",
    "\n",
    withoutPresets
      ? `    /* Module Resolution Options */
    "moduleResolution": "bundler" /* Specify module resolution strategy. */,
    "allowSyntheticDefaultImports": true,     /* Allow default imports from modules with no default export. This does not affect code emit, just typechecking. */
    "esModuleInterop": true${options.monorepoPackageSrcPaths ? "," : ""}                  /* Enables emit interoperability between CommonJS and ES Modules via creation of namespace objects for all imports. Implies 'allowSyntheticDefaultImports'. */
`
      : "",
    "\n    ",
    renderPaths(
      srcDirectory,
      options.enableHashSlash,
      options.monorepoPackageSrcPaths,
    ),
    "\n  }",
    renderReferences(options.monorepoPackageReferences),
    "}\n",
  ].join("");
};

export interface TsconfigCheckJsTemplateOptions {
  composite: boolean;
  node: boolean;
  srcDirectory: string;
}

/** tsconfig.check-js.json.ejs */
export const renderTsconfigCheckJs = ({
  composite,
  node,
  srcDirectory,
}: TsconfigCheckJsTemplateOptions): string => {
  const src = escapeHtml(srcDirectory);
  return `${generatedHeader}{
  "extends": [
    "@pob/root/tsconfigs/base.json",
    "@pob/root/tsconfigs/targets/node-22.json"
  ],
  "compilerOptions": {
    "allowJs": true,
    "checkJs": true,
    "noImplicitAny": false,
    "tsBuildInfoFile": "node_modules/.cache/tsc/tsbuildinfo",
${composite ? '    "composite": true,\n' : ""}${node ? '    "types": ["node"],\n' : ""}    "noEmit": true
  },
  "include": ["${src}/**/*.js","${src}/**/*.mjs","${src}/**/*.cjs", "${src}/**/*.d.ts"]
}
`;
};

/** tsconfig.tools.json.ejs */
export const renderTsconfigTools = (nodeVersion: string): string =>
  `${generatedHeader}{
  "extends": [
    "@pob/root/tsconfigs/strict.json",
    "@pob/root/tsconfigs/targets/node-${escapeHtml(nodeVersion)}.json"
  ],
  "files": [],
  "include": [
    "scripts/**/*.ts",
    "scripts/**/*.mts",
    "scripts/**/*.cts",
    "*.config.js",
    "*.config.ts",
    "*.config.mts",
    "*.config.cts"
  ],
  "compilerOptions": {
    "noEmit": true,
    "incremental": true,
    "tsBuildInfoFile": "node_modules/.cache/tsc/tsbuildinfo-tools",
    "resolveJsonModule": true
  }
}
`;
